// Author: MiYu. Source attack passives, evasion, melee life steal, reflection and cleave consume real hit results.
#include "session.h"
#include <algorithm>
#include <bit>
#include <cmath>

namespace war3 {
namespace {
float number(jass::Real v){return std::bit_cast<float>(v.bits());}
jass::Real real(float v){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(v));}
}
bool ScriptSession::passiveChance(float chance){if(chance<=0)return false;if(chance>=1)return true;return double(random())/4294967296.<chance;}
void ScriptSession::prepareAttack(const UnitState& source,const UnitState& target,CombatProjectile& projectile) {
    bool ranged=projectile.definition.kind!="normal";projectile.damage=std::max(0.f,projectile.damage*(1+(ranged?source.aura.rangedDamage:source.aura.meleeDamage)+source.spellBonus(&UnitBuff::damageBonus)-source.spellBonus(&UnitBuff::damageReduction)+source.equipment.damagePercent)+(ranged?source.aura.rangedFlat:source.aura.meleeFlat)+source.spellBonus(&UnitBuff::flatDamage));projectile.forcedMiss=passiveChance(source.spellBonus(&UnitBuff::missChance));if(source.illusion)return;std::optional<PassiveInfo> critical,bash;float best=projectile.damage;
    for(auto [ability,level]:passiveAbilities(source)){auto& p=passiveInfo(ability,level);if(p.kind==PassiveKind::MissileDefense){projectile.damage*=p.secondary;continue;}if(p.kind==PassiveKind::Feedback){if(passiveTarget(source,target,p))projectile.procs.push_back(p);continue;}if(p.kind==PassiveKind::Demolish){float factor=target.building?p.secondary:target.hero?p.evasion:p.bonus;if(factor>0 && passiveTarget(source,target,p) && passiveChance(p.amount))projectile.damage*=factor;continue;}if(p.kind==PassiveKind::Pulverize){if(!ranged && passiveTarget(source,target,p) && passiveChance(p.amount))projectile.procs.push_back(p);continue;}if((p.kind!=PassiveKind::Critical && p.kind!=PassiveKind::Bash) || (definitions().field(ability,"AbilityData","code")!="ANdb" && !passiveTarget(source,target,p)) || !passiveChance(p.amount))continue;if(p.kind==PassiveKind::Critical){float damage=projectile.damage*std::max(1.f,p.secondary)+p.bonus;if(!critical || damage>best){critical=p;best=damage;}}else if(!target.building && (!ranged || !capability(target,"Amim")) && (!bash || p.bonus>bash->bonus || (p.bonus==bash->bonus && p.duration>bash->duration)))bash=p;}
    if(critical){projectile.damage=best;projectile.neverMiss|=critical->neverMiss;projectile.procs.push_back(*critical);}if(bash){projectile.damage=projectile.damage*std::max(1.f,bash->secondary)+bash->bonus;projectile.neverMiss|=bash->neverMiss;projectile.procs.push_back(*bash);projectile.forcedMiss|=passiveChance(bash->evasion);}
}
bool ScriptSession::evadeAttack(const UnitState& target,const CombatProjectile& projectile) {
    if(projectile.neverMiss)return false;if(projectile.forcedMiss)return true;float evasion=0;for(auto [ability,level]:passiveAbilities(target)){auto& p=passiveInfo(ability,level);if(p.kind==PassiveKind::Evasion)evasion=std::max(evasion,p.amount);else if(p.kind==PassiveKind::Critical)evasion=std::max(evasion,p.evasion);}return passiveChance(evasion);
}
void ScriptSession::attackPassives(const CombatProjectile& p,float damage,const AuraBonuses& defense) {
    if(damage<=0 || !alive(p.source,NativeKind::Unit) || !alive(p.target,NativeKind::Unit))return;auto source=units_.at(p.source),target=units_.at(p.target);if(source->removing || target->removing)return;bool ranged=p.definition.kind!="normal",hostile=enemy(p.owner,target->owner);lavaSpawnHit(p,damage);auto stats=source->aura;auto targetPoint=WorldPoint{target->x,target->y};
    auto attackerDeath=source->deathRevision,defenderDeath=target->deathRevision;for(auto& proc:p.procs)if(proc.kind==PassiveKind::Pulverize && p.visited.size()<=1){pulverizeDamage(p,proc);if(!alive(p.source,NativeKind::Unit) || !alive(p.target,NativeKind::Unit) || source->deathRevision!=attackerDeath || target->deathRevision!=defenderDeath)return;}
    for(auto& proc:p.procs)if(proc.kind==PassiveKind::Bash && p.visited.size()<=1 && number(target->life)>0){SpellInfo spell;spell.ability=proc.ability;spell.buff=proc.buff;spell.duration=proc.duration;spell.heroDuration=proc.heroDuration;applyBuff(p.target,p.source,spell,BuffKind::Stun,!ranged);}
    if(hostile && !source->illusion && !target->building && definitions().unitClasses(target->type).find("mechanical")==std::string::npos && std::max(ranged?0.f:stats.vampiric,source->equipment.vampiric)>0 && alive(p.source,NativeKind::Unit) && !source->removing && number(source->life)>0){unitLife(runtime_.handle("unit",p.source),real(number(source->life)+damage*std::max(ranged?0.f:stats.vampiric,source->equipment.vampiric)));for(auto& [id,aura]:source->auras)if(aura.definition->kind==PassiveKind::Vampiric && aura.definition->buff){SpellInfo art;art.ability=aura.definition->buff;spellVisual(art,"SpecialArt",p.source,{source->x,source->y});}}
    if(!ranged && hostile && (defense.thorns!=0 || defense.thornsFlat!=0) && alive(p.source,NativeKind::Unit) && alive(p.target,NativeKind::Unit)){float reflected=std::max(0.f,damage*defense.thorns+defense.thornsFlat);damageUnit(p.target,p.source,reflected,0,21);if(alive(p.source,NativeKind::Unit))for(auto& [id,aura]:target->auras)if(aura.definition->kind==PassiveKind::Thorns && aura.definition->buff){SpellInfo art;art.ability=aura.definition->buff;spellVisual(art,"SpecialArt",p.source,{source->x,source->y});}}
    if(ranged || source->illusion || !alive(p.source,NativeKind::Unit) || source->removing || number(source->life)<=0)return;std::vector<PassiveInfo> cleaves;for(auto [ability,level]:passiveAbilities(*source)){auto& spell=passiveInfo(ability,level);if(spell.kind==PassiveKind::Cleave)cleaves.push_back(spell);}
    for(auto& spell:cleaves){std::vector<std::uint32_t> victims;for(auto& [id,u]:units_)if(id!=p.source && id!=p.target && passiveTarget(*source,*u,spell) && std::hypot(number(u->x)-number(targetPoint.x),number(u->y)-number(targetPoint.y))<=spell.area)victims.push_back(id);for(auto id:victims){if(!alive(p.source,NativeKind::Unit) || source->removing || number(source->life)<=0)return;if(!alive(id,NativeKind::Unit) || !passiveTarget(*source,*units_.at(id),spell))continue;auto u=units_.at(id);damageUnit(p.source,id,p.damage*spell.amount,p.definition.attackType,5);if(alive(id,NativeKind::Unit)){SpellInfo art;art.ability=spell.ability;spellVisual(art,"SpecialArt",id,{u->x,u->y});}}}
}
}
